import React, { useEffect, useState } from "react";
import axios from "axios";
import ProductCard from "./ProductCard";
import { useLocation, useNavigate } from "react-router-dom";
import "./global.css";

export default function Home() {
  const [products, setProducts] = useState([]);
  const location = useLocation();
  const navigate = useNavigate();

  // swapFor is the product user originally wants to swap (sent from ProductPage)
  const swapFor = location.state?.swapFor || null;

  useEffect(() => {
    axios
      .get("http://localhost:5001/api/products")
      .then((res) => setProducts(res.data))
      .catch((err) => console.log(err));
  }, []);

  const handleSwapSelection = async (selectedProduct) => {
    // ensure swapFor exists
    if (!swapFor) return;

    // ensure user logged in
    const user = JSON.parse(localStorage.getItem("user") || "null");
    if (!user) {
      alert("Please login to send swap request");
      navigate("/login");
      return;
    }

    const priceA = Number(swapFor.price);
    const priceB = Number(selectedProduct.price);
    const diff = Math.abs(priceA - priceB);

    if (diff > 200) {
      alert(`Swap failed ❌ Price difference ₹${diff} — must be ≤ ₹200`);
      return;
    }

    try {
      const res = await axios.post("http://localhost:5001/api/swaps/create", {
        offeredProductId: selectedProduct._id,
        productWantedId: swapFor._id,
        requestedById: user._id,
      });

      if (res.data && res.data.success) {
        alert("Swap Successful! 🎉");
        // clear state by navigating to home without swap state
        navigate("/", { replace: true });
      } else {
        alert("Swap request failed");
      }
    } catch (err) {
      console.error(err);
      const msg = err.response?.data?.error || "Swap request failed";
      alert(msg);
    }
  };

  const handleProductClick = (p) => {
    if (swapFor) {
      // swap selection mode
      handleSwapSelection(p);
    } else {
      navigate(`/product/${p._id}`);
    }
  };

  return (
    <div className="home-page">
      <div
        className="hero-section"
        style={{
          backgroundImage:
            "url('https://images.unsplash.com/photo-1523381210434-271e8be1f52b?w=1400')",
          backgroundSize: "cover",
          backgroundPosition: "center",
          height: 300,
          borderRadius: 12,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          color: "white",
          textShadow: "0 2px 10px rgba(0,0,0,0.4)",
          margin: "20px",
        }}
      >
        <h1>Welcome to Rewear</h1>
        <p className="tagline">Buy • Sell • Swap — A Sustainable Marketplace 🌱</p>
      </div>

      <div className="action-bar">
        <div className="action-left">
          <button
            onClick={() => {
              // normal buy/swap view (no state)
              navigate("/", { replace: true });
            }}
            className="action-btn"
          >
            Buy / Swap
          </button>
        </div>

        <div className="action-right">
          <button
            onClick={() => navigate("/create")}
            className="action-btn"
          >
            Sell
          </button>
        </div>
      </div>

      {swapFor ? (
        <h2 style={{ textAlign: "center", marginTop: 12 }}>
          Select a product to swap with: <strong>{swapFor.title}</strong> (₹{swapFor.price})
        </h2>
      ) : (
        <h2 className="section-title">Available Products</h2>
      )}

      <div className="product-grid">
        {products.length ? (
          products.map((p) => (
            <div key={p._id} onClick={() => handleProductClick(p)}>
              <ProductCard product={p} />
            </div>
          ))
        ) : (
          <p style={{ textAlign: "center", padding: 20 }}>No products yet.</p>
        )}
      </div>
    </div>
  );
}
